"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[32360],{3331:(e,a,o)=>{o.d(a,{R:()=>r,x:()=>l});var s=o(36672);const n={},i=s.createContext(n);function r(e){const a=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function l(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),s.createElement(i.Provider,{value:a},e.children)}},37525:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>d,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"Remembering Bob Lee","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/es/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/es/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6 de abril de 2023","top_news":"Remembering Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/es/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/es/2023/04/05"}}');var n=o(23420),i=o(3331);const r={localized_date:"6 de abril de 2023",top_news:"Remembering Bob Lee"},l="2023-04-06",d={},c=[{value:"Remembering Bob Lee",id:"remembering-bob-lee",level:2},{value:"Bob Lee, ex CTO de Square, ha muerto tras ser apu\xf1alado en San Francisco",id:"bob-lee-ex-cto-de-square-ha-muerto-tras-ser-apu\xf1alado-en-san-francisco",level:2},{value:"iOS permite a las operadoras a\xf1adir redes WiFi a las que no puedes evitar unirte",id:"ios-permite-a-las-operadoras-a\xf1adir-redes-wifi-a-las-que-no-puedes-evitar-unirte",level:2},{value:"Fundamentos del aprendizaje profundo para una difusi\xf3n estable",id:"fundamentos-del-aprendizaje-profundo-para-una-difusi\xf3n-estable",level:2},{value:"CAN Injection: Robo de coches sin llave",id:"can-injection-robo-de-coches-sin-llave",level:2},{value:"Los ingenieros de Firefox descubren un fallo de Windows Defender que provoca un alto uso de la CPU",id:"los-ingenieros-de-firefox-descubren-un-fallo-de-windows-defender-que-provoca-un-alto-uso-de-la-cpu",level:2},{value:"Segment Anything Model (SAM) puede &quot;recortar&quot; cualquier objeto de una imagen",id:"segment-anything-model-sam-puede-recortar-cualquier-objeto-de-una-imagen",level:2},{value:"El whitepaper de Bitcoin se esconde en cada copia de macOS",id:"el-whitepaper-de-bitcoin-se-esconde-en-cada-copia-de-macos",level:2},{value:"El ex CTO de Square Bob Lee muere apu\xf1alado en el centro de San Francisco",id:"el-ex-cto-de-square-bob-lee-muere-apu\xf1alado-en-el-centro-de-san-francisco",level:2},{value:"The case for banning children from social media",id:"the-case-for-banning-children-from-social-media",level:2},{value:"Dang va a tener 65.535 puntos de karma pronto",id:"dang-va-a-tener-65535-puntos-de-karma-pronto",level:2},{value:"Redes neuronales: De cero a h\xe9roe",id:"redes-neuronales-de-cero-a-h\xe9roe",level:2},{value:"Un truco para alcanzar la fluidez: Deja tu trabajo roto",id:"un-truco-para-alcanzar-la-fluidez-deja-tu-trabajo-roto",level:2},{value:"\xbfSe limpia la RAM antes de usarla en otro contenedor LXC?",id:"se-limpia-la-ram-antes-de-usarla-en-otro-contenedor-lxc",level:2},{value:"Perspectiva: BI con WebAssembly de c\xf3digo abierto",id:"perspectiva-bi-con-webassembly-de-c\xf3digo-abierto",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"OpenAI Tokenizer",id:"openai-tokenizer",level:2},{value:"Tabloid - El lenguaje de programaci\xf3n de titulares clickbait",id:"tabloid---el-lenguaje-de-programaci\xf3n-de-titulares-clickbait",level:2},{value:"GPT4 simulando un servidor FTP en ftp.disney.com",id:"gpt4-simulando-un-servidor-ftp-en-ftpdisneycom",level:2},{value:"Uso de mmap para que LLaMA cargue m\xe1s r\xe1pido",id:"uso-de-mmap-para-que-llama-cargue-m\xe1s-r\xe1pido",level:2}];function t(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,n.jsx)(a.h2,{id:"remembering-bob-lee",children:"Remembering Bob Lee"}),"\n",(0,n.jsx)(a.p,{children:"La comunidad tecnol\xf3gica llora la p\xe9rdida de Bob Lee, una figura muy conocida en el sector. Lee fue un defensor de Java, habiendo trabajado en Google y Square, y era conocido por su trabajo en el marco de inyecci\xf3n de dependencias Guice. Tambi\xe9n fue cofundador de Android Alliance, una iniciativa destinada a promover la innovaci\xf3n en el ecosistema Android. Las contribuciones de Lee al mundo de la tecnolog\xeda fueron ampliamente reconocidas, y sus colegas y compa\xf1eros le echar\xe1n mucho de menos. Muchos han compartido sus condolencias en las redes sociales, recordando a Lee como un mentor y amigo que siempre dedicaba tiempo a los dem\xe1s. Descansa en paz, Bob Lee."}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, coautor de las bibliotecas Guice y Java, famoso por sus conocimientos t\xe9cnicos, su amabilidad y su humildad, ha fallecido. Su muerte ha enlutado a la comunidad tecnol\xf3gica y ha llevado a muchas personas a compartir sus recuerdos y an\xe9cdotas sobre \xe9l. El legado de innovaci\xf3n y pasi\xf3n de Lee ha inspirado a muchos, y sus contribuciones a la industria se echar\xe1n de menos. Aunque algunos comentarios divagaban, la mayor\xeda compart\xeda pensamientos y experiencias positivas sobre Bob."]}),"\n",(0,n.jsx)(a.h2,{id:"bob-lee-ex-cto-de-square-ha-muerto-tras-ser-apu\xf1alado-en-san-francisco",children:"Bob Lee, ex CTO de Square, ha muerto tras ser apu\xf1alado en San Francisco"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, el creador de Cash App como Director de Tecnolog\xeda en Square, fue identificado como el hombre que fue asesinado en San Francisco debido a un incidente de apu\xf1alamiento; el evento ha conmocionado al mundo de la tecnolog\xeda, con la gente reaccionando a la repentina noticia. La polic\xeda no ha realizado ninguna detenci\xf3n ni ha facilitado informaci\xf3n sobre posibles sospechosos. Lee ten\xeda 43 a\xf1os, era el fundador de Cash App y trabajaba como Jefe de Producto en MobileCoin en el momento de su muerte."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nBob Lee, antiguo Director T\xe9cnico de Square, asesinado en San Francisco, suscita un debate sobre delincuencia y gobernanza. Los comentarios abarcan la disparidad de la riqueza, la falta de vivienda, el aburguesamiento y las posibles soluciones. Se cuestionan los sistemas pol\xedticos y la falta de fiabilidad de las estad\xedsticas sobre delincuencia en las ciudades estadounidenses. Los usuarios debaten las posibles causas de la delincuencia, entre ellas la emigraci\xf3n masiva, la desigualdad econ\xf3mica, el impacto de los sistemas judiciales y la falta de respuesta de la polic\xeda. Comparar la delincuencia entre diferentes pa\xedses o culturas no es \xfatil. El problema de la delincuencia es complejo y no es el resultado de un \xfanico factor."]}),"\n",(0,n.jsx)(a.h2,{id:"ios-permite-a-las-operadoras-a\xf1adir-redes-wifi-a-las-que-no-puedes-evitar-unirte",children:"iOS permite a las operadoras a\xf1adir redes WiFi a las que no puedes evitar unirte"}),"\n",(0,n.jsx)(a.p,{children:'El sistema operativo iOS permite a los operadores a\xf1adir redes WiFi a las que los usuarios no pueden dejar de unirse. Esta funci\xf3n preocupa a los usuarios de iPhone con planes de datos limitados o que tienen problemas de privacidad. La funci\xf3n est\xe1 pensada para ayudar a las operadoras a poner en marcha puntos de acceso WiFi, pero tambi\xe9n les permite a\xf1adir redes WiFi p\xfablicas a las que los usuarios se conectan sin saberlo, con la posibilidad de recopilar datos confidenciales. Los usuarios tienen opciones limitadas para desactivar la funci\xf3n, como desactivar el WiFi por completo o elegir "Olvidar esta red" cada vez que se encuentren con ella. Algunos usuarios piden a Apple que a\xf1ada m\xe1s control sobre esta funci\xf3n, mientras que otros sugieren utilizar una VPN para proteger sus datos.'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 permite a las operadoras a\xf1adir redes gestionadas a los dispositivos, reducir los costes de la telefon\xeda m\xf3vil y evitar la desactivaci\xf3n de la uni\xf3n autom\xe1tica, sin que exista actualmente ninguna forma de eliminar estas redes aparte de restablecer los ajustes de red. Los usuarios denuncian que T-Mobile les roba datos y que las redes Wingman en vuelo no se desactivan, y expresan su sorpresa por el hecho de que las operadoras dicten las conexiones WiFi sin que el usuario pueda recurrir. Se debate c\xf3mo conseguir un control total del dispositivo, y algunos usuarios recomiendan GrapheneOS para las actualizaciones de seguridad. Se critica a los puntos de acceso WiFi de las operadoras por interrumpir las conexiones de los dispositivos locales, aunque algunos consideran que esta funci\xf3n es \xfatil en zonas muy concurridas."]}),"\n",(0,n.jsx)(a.h2,{id:"fundamentos-del-aprendizaje-profundo-para-una-difusi\xf3n-estable",children:"Fundamentos del aprendizaje profundo para una difusi\xf3n estable"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" es un curso de m\xe1s de 30 horas de contenido en v\xeddeo que incluye la cobertura del algoritmo Stable Diffusion desde cero, en estrecha colaboraci\xf3n con expertos de Stable.ai y Hugging Face. El curso proporciona una cobertura rigurosa de las \xfaltimas t\xe9cnicas y va m\xe1s all\xe1 incluso de lo que incluye Stable Diffusion, por lo que es un gran objetivo de aprendizaje por muchas razones, sin embargo, para sacar el m\xe1ximo provecho de este curso, usted debe ser un practicante de aprendizaje profundo razonablemente confiado. A lo largo del curso, exploraremos m\xe9todos de difusi\xf3n, implementaremos nuestros propios modelos desde cero, dominaremos conceptos de Python y PyTorch para implementar nuestros modelos. Cubriremos fundamentos de difusi\xf3n, optimizadores de aprendizaje profundo, conceptos de Python, fundamentos b\xe1sicos, generaci\xf3n de n\xfameros pseudoaleatorios, arquitecturas de redes neuronales, arquitecturas generativas, transformadores y entrenamiento de precisi\xf3n mixta.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),".\nDeep Learning Foundations to Stable Diffusion' explora el modelado generativo moderno, mientras que algunos recomiendan centrarse en el marketing. El curso de aprendizaje profundo de Fast.ai crea un marco de programaci\xf3n desde cero y es recomendable para cualquiera que est\xe9 interesado en \xe9l. Existe un debate en torno a los peligros potenciales de la IA avanzada y la importancia de la regulaci\xf3n y las consideraciones \xe9ticas. Los comentaristas sugieren prohibir la producci\xf3n de IA, pero no es una soluci\xf3n a largo plazo a menos que todos los pa\xedses lo hagan. El curso de FastAI no tiene ning\xfan sesgo pol\xedtico o religioso, y su contenido se considera de primera categor\xeda. El curso es accesible a cualquier persona con conocimientos b\xe1sicos de matem\xe1ticas de secundaria y abarca conceptos avanzados."]}),"\n",(0,n.jsx)(a.h2,{id:"can-injection-robo-de-coches-sin-llave",children:"CAN Injection: Robo de coches sin llave"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nLos ladrones de coches est\xe1n utilizando una nueva t\xe9cnica denominada inyecci\xf3n CAN para eludir los sistemas de llave inteligente de los coches modernos aprovechando las vulnerabilidades del protocolo de comunicaci\xf3n del bus CAN. Los sofisticados sistemas de seguridad de los coches, incluidos los inmovilizadores del motor, se han vuelto vulnerables. Los ladrones utilizan un dispositivo llamado CAN Injector para robar coches sin llave inyectando mensajes falsos en el sistema de comunicaci\xf3n interno del coche. El dispositivo cuesta 10 d\xf3lares y contiene un chip PIC18F, un firmware preprogramado, un transceptor y un circuito adicional. Una soluci\xf3n r\xe1pida o la mensajer\xeda criptogr\xe1fica pueden derrotar al CAN Injector. Ian Haken esboza varias formas en que los fabricantes de autom\xf3viles podr\xedan contribuir a la seguridad de los veh\xedculos, pero la explotaci\xf3n delictiva de esta t\xe9cnica est\xe1 muy extendida. Se trata de un problema que afecta a toda la industria y que requiere una actualizaci\xf3n del software de la ECU para derrotar a los ladrones."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nUna t\xe9cnica de robo de coches sin llave conocida como CAN Injection fue destacada en Hacker News. Los consumidores deben tener cuidado con el cifrado o la firma del bus CAN, ya que puede limitar las herramientas de diagn\xf3stico de terceros, lo que aumenta los costes de reparaci\xf3n. El bus CAN controla m\xfaltiples funciones del veh\xedculo, y los fabricantes de veh\xedculos optimizan los costes sin piedad. Los fabricantes de autom\xf3viles tienen la obligaci\xf3n legal de separarse de los distribuidores, pero algunos comentarios critican que se atengan al esp\xedritu de la ley. Las marcas de autom\xf3viles de gama alta utilizan diversas medidas de seguridad para evitar el pirateo de los coches, como inmovilizadores con protocolos criptogr\xe1ficos adecuados para autenticar los mensajes de arranque y arranque y tramas CAN/FlexRay/Ethernet firmadas para evitar la suplantaci\xf3n de mensajes. Los coches baratos son un objetivo f\xe1cil de robar, mientras que los caros son objeto de robos violentos. El exploit descrito en el art\xedculo podr\xeda aplicarse a casi cualquier veh\xedculo no conectado fabricado en la \xfaltima d\xe9cada. El uso del bus CAN en sistemas cr\xedticos como la aviaci\xf3n y la automoci\xf3n se debe a su sencillez de cableado y rentabilidad."]}),"\n",(0,n.jsx)(a.h2,{id:"los-ingenieros-de-firefox-descubren-un-fallo-de-windows-defender-que-provoca-un-alto-uso-de-la-cpu",children:"Los ingenieros de Firefox descubren un fallo de Windows Defender que provoca un alto uso de la CPU"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Este texto no est\xe1 relacionado con el tema)."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nLos ingenieros de Firefox han encontrado un fallo en Windows Defender que provoca un uso excesivo de la CPU en el navegador de Mozilla. Microsoft est\xe1 lanzando un parche para solucionarlo. Otros productos antivirus tambi\xe9n podr\xedan causar problemas de uso de la CPU. Firefox realiza m\xe1s llamadas al sistema que Chrome por motivos de seguridad. Una comparaci\xf3n muestra que Firefox es m\xe1s r\xe1pido que Chrome en algunas pruebas. Los expertos discuten las limitaciones de Defender, sugieren sandboxing y hardware MFA. Los usuarios debaten sobre la eficacia de Defender frente al software antivirus de terceros. Algunos usuarios informan de problemas con Defender que causan un acceso lento al sistema de archivos."]}),"\n",(0,n.jsx)(a.h2,{id:"segment-anything-model-sam-puede-recortar-cualquier-objeto-de-una-imagen",children:'Segment Anything Model (SAM) puede "recortar" cualquier objeto de una imagen'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://segment-anything.com/",children:"Original"}),".\nEl Segment Anything Model (SAM) desarrollado por Meta AI puede aislar cualquier objeto de una imagen con gran precisi\xf3n. Puede identificar y segmentar objetos con \xe9xito, incluso cuando son parcialmente visibles u ocluidos. SAM mejora los modelos desarrollados anteriormente que se basaban en pistas de localizaci\xf3n u objetos destacados. En lugar de utilizar estas claves, SAM aplica el metaaprendizaje, aprovechando el aprendizaje de un modelo existente, para poder detectar conjuntos de datos peque\xf1os y sesgados u objetos no vistos. SAM puede utilizarse para aplicaciones pr\xe1cticas, como la edici\xf3n de im\xe1genes, as\xed como para la investigaci\xf3n en el campo de la visi\xf3n por ordenador."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),'.\nSAM de Meta AI permite generar m\xe1scaras en tiempo real para "recortar" cualquier objeto de una imagen. La licencia del modelo y sus impresionantes capacidades de inferencia pueden hacerlo popular entre los expertos en tecnolog\xeda. Los problemas incluyen una velocidad m\xe1s lenta con el modelo RTX 2080ti 11GB y una precisi\xf3n limitada con objetos transparentes. Algunos ven la estrategia de lanzamiento de Meta AI como parte de un impulso de adopci\xf3n de RA. Los usuarios alaban la reducci\xf3n de costes de anotaci\xf3n de datos de SAM, pero critican su velocidad y la comparan con iOS. El desarrollo tambi\xe9n podr\xeda tener una aplicaci\xf3n potencial para c\xe1maras de seguridad y la integraci\xf3n de AdobeAI.']}),"\n",(0,n.jsx)(a.h2,{id:"el-whitepaper-de-bitcoin-se-esconde-en-cada-copia-de-macos",children:"El whitepaper de Bitcoin se esconde en cada copia de macOS"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),'.\nUna copia en PDF del whitepaper de Bitcoin de Satoshi Nakamoto ha sido descubierta en cada copia moderna de macOS desde Mojave en 2018, y se puede acceder a ella a trav\xe9s de un documento de muestra en la utilidad de Captura de Imagen. El whitepaper se utiliza como un documento de muestra para un dispositivo llamado "Virtual Scanner II", que est\xe1 oculto o no est\xe1 instalado para todos de forma predeterminada. Aunque el motivo de su inclusi\xf3n a\xfan no est\xe1 claro, es posible que se tratara de un PDF multip\xe1gina c\xf3modo y ligero para realizar pruebas. Hay muy poca informaci\xf3n disponible en l\xednea sobre Virtual Scanner II o la inclusi\xf3n del documento en macOS.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nEl libro blanco de Bitcoin est\xe1 oculto en todas las copias de macOS desde 2019; se especula sobre por qu\xe9 est\xe1 incluido, y los usuarios advierten contra la miner\xeda en iPhones. La suma hash coincide con la versi\xf3n original, pero las teor\xedas var\xedan sobre por qu\xe9 se incluye. Surgieron quejas sobre el respaldo a un esquema Ponzi, pero los usuarios aclaran que est\xe1 oculto. Puede que Apple lo haya incluido por comodidad, pero la publicaci\xf3n suscita el di\xe1logo sobre el impacto de Bitcoin. Los usuarios comentan la imagen utilizada en un art\xedculo, el tama\xf1o del archivo PDF y la p\xe9rdida de diversi\xf3n art\xedstica de la tecnolog\xeda."]}),"\n",(0,n.jsx)(a.h2,{id:"el-ex-cto-de-square-bob-lee-muere-apu\xf1alado-en-el-centro-de-san-francisco",children:"El ex CTO de Square Bob Lee muere apu\xf1alado en el centro de San Francisco"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nEl ex CTO de Square Bob Lee fue apu\xf1alado hasta la muerte en el centro de San Francisco, seg\xfan The Standard. Lee era el Director de Producto de MobileCoin, una empresa de criptomonedas de San Francisco, y un miembro muy querido de las comunidades de desarrollo de software y tecnolog\xeda del \xc1rea de la Bah\xeda. La polic\xeda de San Francisco no ha facilitado m\xe1s detalles ni la identidad de la v\xedctima, y est\xe1 solicitando testigos presenciales y grabaciones de v\xeddeo para su investigaci\xf3n. San Francisco ha sufrido 12 homicidios hasta el 2 de abril, dos m\xe1s que en el mismo periodo del a\xf1o pasado. The Standard cubre historias importantes, incluidos asuntos de justicia penal en San Francisco, y ofrece boletines informativos y una visi\xf3n general de la pol\xedtica y la cultura de San Francisco."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nEl ex CTO de Square, Bob Lee, muere apu\xf1alado en San Francisco; los comentarios hacen referencia a nuevos detalles."]}),"\n",(0,n.jsx)(a.h2,{id:"the-case-for-banning-children-from-social-media",children:"The case for banning children from social media"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nEl debate sobre la prohibici\xf3n del acceso de los ni\xf1os a las redes sociales es constante debido a la preocupaci\xf3n por la adicci\xf3n y la negatividad. Se han aprobado algunos proyectos de ley para restringir el acceso de los menores a los sitios de medios sociales y eliminar las funciones adictivas, pero esto plantea implicaciones para las libertades civiles y limita el acceso a noticias y perspectivas diferentes, lo que plantea la cuesti\xf3n de c\xf3mo deben tratarse los medios sociales. Aunque los tribunales han anulado las protecciones en l\xednea para la seguridad infantil, la creaci\xf3n de mensajes contra la adicci\xf3n y las restricciones legales presentan conflictos potenciales con los derechos de la Primera Enmienda, y los padres pueden tener que recurrir a retirar f\xedsicamente las pantallas. Salvaguardar a los ni\xf1os en l\xednea es un debate pol\xedtico y cultural, que deja poca confianza en la capacidad del gobierno para regular las empresas de medios sociales."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nUn art\xedculo aboga por prohibir las redes sociales a los menores de 18 a\xf1os debido a la posible adicci\xf3n a las drogas; la regulaci\xf3n de estos contenidos plantea dificultades. Un debate sobre la definici\xf3n y la influencia de los anuncios dirigidos a los ni\xf1os suscita dudas sobre la regulaci\xf3n de la publicidad. Se plantean los efectos nocivos de las redes sociales en la salud mental y el desarrollo personal, lo que lleva a sugerir la prohibici\xf3n de las redes sociales corporativas y de los feeds algor\xedtmicos. Una prohibici\xf3n general de las redes sociales no se considera la soluci\xf3n; se necesitan enfoques matizados. Los usuarios de Discussion Service discuten formas eficaces de limitar el tiempo frente a la pantalla y combatir los efectos negativos. El debate se centra en encontrar un equilibrio entre la libertad individual y la responsabilidad social. La preocupaci\xf3n por el control de las redes sociales y la liberaci\xf3n de dopamina en el cerebro suscitan debates sobre la prohibici\xf3n de las redes sociales potenciadas por algoritmos. La viabilidad y la posible intrusi\xf3n en la intimidad se destacan como preocupaciones sobre los controles de identificaci\xf3n obligatorios para las cuentas de las redes sociales. No se habla de nuevas tecnolog\xedas ni de grandes lanzamientos."]}),"\n",(0,n.jsx)(a.h2,{id:"dang-va-a-tener-65535-puntos-de-karma-pronto",children:"Dang va a tener 65.535 puntos de karma pronto"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nSe espera que el usuario de Discussion Service 'dang' alcance pronto los 65.535 puntos de karma, que es el l\xedmite m\xe1ximo debido a que el sistema utiliza un entero de 16 bits con signo."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, alias Dang, a punto de alcanzar los 65.535 puntos de karma. La secci\xf3n de comentarios se llena de elogios al trabajo de Dang. Los usuarios especulan sobre si el karma se dar\xe1 la vuelta y discuten el cambio a int de 32 bits. Se cuestiona el estilo de moderaci\xf3n y la implicaci\xf3n de Y Combinator. Alcanzar un karma alto se ve como una forma de mostrar aprecio por el trabajo de Dang. Alcanzar hitos de karma m\xe1s altos permite capacidades adicionales en Discussion Service, tales como upvoting/downvoting."]}),"\n",(0,n.jsx)(a.h2,{id:"redes-neuronales-de-cero-a-h\xe9roe",children:"Redes neuronales: De cero a h\xe9roe"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nEl curso "Neural Networks: Zero to Hero" de Andrej Karpathy ense\xf1a a construir redes neuronales desde cero en c\xf3digo. El curso comienza con los fundamentos de la retropropagaci\xf3n y avanza hasta las modernas redes neuronales profundas como GPT. El curso se centra en los modelos ling\xfc\xedsticos, ya que son un lugar excelente para aprender el aprendizaje profundo. Los prerrequisitos incluyen programaci\xf3n s\xf3lida y matem\xe1ticas de nivel introductorio. El curso incluye la construcci\xf3n de micrograd, makemore, un MLP, y la inmersi\xf3n en algunos de los aspectos internos de MLPs. Tambi\xe9n se aborda c\xf3mo convertirse en un Backprop Ninja y c\xf3mo construir WaveNet. El curso culmina con la creaci\xf3n de GPT. Los v\xeddeos ofrecen una explicaci\xf3n paso a paso y se centran en el desarrollo de la competencia y la intuici\xf3n sobre c\xf3mo se optimizan las redes neuronales. El curso recomienda a los asistentes ver los v\xeddeos anteriores de makemore para sentirse c\xf3modos con el marco de modelado autorregresivo del lenguaje y con los fundamentos de los tensores y PyTorch nn.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nEl curso 'Neural Networks: Zero to Hero' de Andrej Karpathy gana m\xe1s de 300 puntos en Hacker News en 6 horas. Los usuarios de Discussion Service elogian su estilo de ense\xf1anza y recomiendan codificar despu\xe9s de ver los v\xeddeos. Su curso de ML dirigido por compa\xf1eros recibe comentarios positivos a pesar de no mencionarlo. La sintaxis espec\xedfica de Python en los v\xeddeos puede suponer un reto para algunos usuarios. Un debate eval\xfaa el \xe9nfasis del curso en la regresi\xf3n log\xedstica y el perceptr\xf3n. Los participantes consideran que el curso es f\xe1cil de entender y recomiendan otros cursos para principiantes. Algunos usuarios cuestionan los conocimientos m\xednimos de los desarrolladores web, y un usuario tiene una teor\xeda sobre el v\xednculo entre ML y el \xe1lgebra de Hopf."]}),"\n",(0,n.jsx)(a.h2,{id:"un-truco-para-alcanzar-la-fluidez-deja-tu-trabajo-roto",children:"Un truco para alcanzar la fluidez: Deja tu trabajo roto"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nEl art\xedculo analiza la dificultad de entrar en un estado de "flujo" en tareas de ingenier\xeda y proporciona un truco para volver a entrar en flujo. El autor sugiere dejar el trabajo en un estado obviamente roto pero f\xe1cil de arreglar antes de apartarse. Esto permite tener un punto de partida claro al volver al trabajo, creando impulso y confianza. El art\xedculo reconoce que este enfoque puede no ser universal o aplicable en entornos de equipo, pero invita a comentar otros trucos. Tambi\xe9n se menciona brevemente la ingenier\xeda de censos y las oportunidades de empleo.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nLos usuarios de Discussion Service comparten consejos para alcanzar el estado de flujo dejando el trabajo sin terminar, incluido el m\xe9todo de "aparcar mirando hacia abajo". Un director de ingenier\xeda puso en pr\xe1ctica lo de dejar el trabajo a las 6 de la tarde para evitar el agotamiento, pero lo puso fin debido al presentismo. Los usuarios debaten las ventajas y los riesgos de las normas estrictas de horarios y de cambiar la cultura laboral. Algunos comparten consejos de productividad como anotar los siguientes pasos y practicar TDD. Dejar el c\xf3digo en un estado "roto" puede ayudar a reanudarlo m\xe1s tarde, pero tiene resultados dispares.']}),"\n",(0,n.jsx)(a.h2,{id:"se-limpia-la-ram-antes-de-usarla-en-otro-contenedor-lxc",children:"\xbfSe limpia la RAM antes de usarla en otro contenedor LXC?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nUn post en Information Security Stack Exchange pregunta si la RAM se limpia antes de su uso en otro contenedor LXC, lo que lleva a una discusi\xf3n de RAM-overprovisioning en LXC, con un usuario comentando que la memoria asignada a un proceso anterior en un contenedor se borra. Un post en Hacker News profundiza m\xe1s, discutiendo las bibliotecas compartidas y las protecciones del espacio de nombres de usuario, y una respuesta aclara que las p\xe1ginas se borran antes de la asignaci\xf3n, el sobreaprovisionamiento no causa compartici\xf3n, y la memoria LXC se asigna a los procesos a trav\xe9s de espacios de nombres, pero los procesos est\xe1n separados de los recursos del host. Por \xfaltimo, se se\xf1ala que la gesti\xf3n de memoria basada en glibc no implica limpieza y que las p\xe1ginas libres pueden contener datos."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nLos usuarios de Hacker News debatieron sobre la eficacia y la necesidad de la puesta a cero autom\xe1tica de la memoria en Linux, y algunos sugirieron m\xe9todos alternativos para limpiar la memoria no utilizada. Un usuario se\xf1al\xf3 que el problema radica en el dise\xf1o de la llamada al sistema fork() de UNIX, y que muchos programas que hacen un uso intensivo de la memoria siguen teniendo problemas con la OOM. En otros comentarios se discuten las diferencias entre la asignaci\xf3n de memoria con sobrecompromiso y sin sobrecompromiso en Linux y la importancia de establecer l\xedmites. El art\xedculo ofrece perspectivas matizadas sobre la asignaci\xf3n de memoria en Linux y est\xe1 dirigido a expertos en la materia."]}),"\n",(0,n.jsx)(a.h2,{id:"perspectiva-bi-con-webassembly-de-c\xf3digo-abierto",children:"Perspectiva: BI con WebAssembly de c\xf3digo abierto"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective es un componente interactivo de an\xe1lisis y visualizaci\xf3n de datos, dise\xf1ado para streaming y grandes conjuntos de datos con informes, cuadros de mando y cuadernos configurables. Dispone de un motor de consulta de streaming eficiente en memoria en C++ y Python y una interfaz de usuario empaquetada como elemento personalizado basado en WebAssembly o WebSocket. La interfaz de usuario incluye cuadros de mando interactivos que pueden integrarse en cualquier marco de aplicaci\xf3n web. Perspective.js se basa en WebAssembly y Apache Arrow para ofrecer un rendimiento similar al de un escritorio en el navegador. PerspectivePython implementa la API de Perspective directamente en Python para investigaci\xf3n o producci\xf3n. Hay widgets virtualizados y escalables, y el proyecto est\xe1 disponible en GitHub con gu\xedas para usuarios y programadores."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nPerspective, herramienta de BI de c\xf3digo abierto basada en WebAssembly, elogiada por su potente funcionalidad, a pesar de sus problemas de rendimiento: entre las soluciones sugeridas se incluye el uso de una opci\xf3n m\xe1s ligera. Los creadores de Perspective trabajan para mejorar el rendimiento y la compatibilidad m\xf3vil. Se plantean algunas dudas sobre la compatibilidad con Firefox y la accesibilidad o el dise\xf1o sin teclado. Se discuten las limitaciones de Sciter y se considera que las bibliotecas Tauri pueden ser \xfatiles. Es necesario mejorar el rendimiento del proyecto Perspective."]}),"\n",(0,n.jsx)(a.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\nGrid World", de Alexander Miller, explora el papel de las cuadr\xedculas en su vida desde la infancia hasta la edad adulta, incluido su impacto en la tecnolog\xeda, el arte y la navegaci\xf3n. El art\xedculo aborda el poder de las cuadr\xedculas para cartografiar y controlar el espacio, como se ve en juegos como Battleship y Chess. La cuadr\xedcula se convierte en un eje central que enlaza las experiencias personales de Miller, mostrando c\xf3mo se convierte en parte de nuestras vidas. Miller cre\xf3 la cuadr\xedcula para The HTML Review en 2023.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nLos usuarios de Discussion Service est\xe1n fascinados por la excepcional maestr\xeda y artesan\xeda de Grid World en el dise\xf1o y desarrollo web y su impacto en la percepci\xf3n. El art\xedculo explora la subestructura de la cuadr\xedcula en nuestros recuerdos y en el mundo, con im\xe1genes pixel art. Los comentarios destacan la conexi\xf3n con la neurociencia de las celdas cuadriculadas, al tiempo que plantean cr\xedticas sobre la racionalizaci\xf3n y el manto de la cuadr\xedcula sobre la naturaleza. A un usuario le resulta dif\xedcil perfeccionar los aspectos de dise\xf1o visual de su proyecto personal. Los usuarios debaten sobre las cuadr\xedculas de Queens y la historia que hay detr\xe1s de ellas. Un usuario de Discussion Service comparte sus ideas sobre la conformidad de la cuadr\xedcula de las calles de Nueva York. Una decoraci\xf3n en forma de mesa genera pasillos desordenados tenuemente iluminados mientras evoluciona a trav\xe9s del tiempo, construida con javascript plano sin bibliotecas para un divertido ejercicio t\xe9cnico."]}),"\n",(0,n.jsx)(a.h2,{id:"openai-tokenizer",children:"OpenAI Tokenizer"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nLa API OpenAI es una tecnolog\xeda que requiere que JavaScript est\xe9 habilitado."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI ha lanzado un nuevo tokenizador para comprender mejor los modelos GPT. El tokenizador divide el texto en unidades de subpalabras para un procesamiento eficiente, pero carecen de significado inherente. Los usuarios de Discussion Service discuten las limitaciones de la herramienta, como la agrupaci\xf3n basada en espacios y el tratamiento de las may\xfasculas. Las codificaciones creadas mediante pares de bytes no suelen ser adecuadas para las lenguas infrarrepresentadas. OpenAI cobra por token debido al funcionamiento basado en tokens del modelo."]}),"\n",(0,n.jsx)(a.h2,{id:"tabloid---el-lenguaje-de-programaci\xf3n-de-titulares-clickbait",children:"Tabloid - El lenguaje de programaci\xf3n de titulares clickbait"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid es un nuevo lenguaje de programaci\xf3n creado para generar titulares rid\xedculos y dignos de clics, parecidos a los que aparecen en los tabloides. El lenguaje utiliza una combinaci\xf3n de procesamiento del lenguaje natural, aprendizaje autom\xe1tico y crowd-sourcing para crear titulares con patrones ling\xfc\xedsticos clickbaity. Es un lenguaje divertido y entretenido que no sirve para nada, pero es un excelente ejemplo de c\xf3mo la programaci\xf3n puede ser \xfatil y divertida a la vez. El creador de Tabloid planea utilizarlo para crear una plataforma que permita a cualquiera crear sus propios titulares clickbait. Los usuarios de Discussion Service encuentran esta herramienta interesante y una forma \xfatil de entender el procesamiento del lenguaje natural."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nUn proyecto reciente en Hacker News llamado Tabloid - The Clickbait Headline Programming Language. El proyecto es fascinante, escrito por un autor que afirma haber escrito otros lenguajes posiblemente m\xe1s \xfatiles. Un usuario de Discussion Service public\xf3 un programa en Tabloid que toma cinco n\xfameros y devuelve el producto de los tres primeros m\xe1s el producto de los dos \xfaltimos. El autor es alguien que ha enviado muchos proyectos interesantes, incluso usando Oak para construir un mont\xf3n de infraestructura de software personal, entre otras cosas. Otro usuario de Discussion Service coment\xf3 que escribir todo desde cero es lo m\xe1s viable para desarrolladores solitarios, pero no para equipos, donde es mejor optar por lo "aburrido".']}),"\n",(0,n.jsx)(a.h2,{id:"gpt4-simulando-un-servidor-ftp-en-ftpdisneycom",children:"GPT4 simulando un servidor FTP en ftp.disney.com"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nChat GPT-4 es h\xe1bil simulando un servidor FTP para Disney, utilizando la herramienta cli ftp base y llegando a ejecutar comandos como lo har\xeda un usuario real. El servidor simulado incluye contenido exclusivo de Disney en carpetas como pel\xedculas, bandas sonoras y fondos de pantalla, y GPT-4 demuestra ser capaz de navegar por sistemas de archivos locales y remotos. La nueva tecnolog\xeda funciona bien, superando las expectativas y demostrando su capacidad para crear contenidos atractivos para los entusiastas de Disney. El art\xedculo insin\xfaa futuros usos de GPT-4 en plugins de int\xe9rprete de c\xf3digo que permitan acceder a servidores inventados desde clientes FTP."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),'.\nUn art\xedculo en Hacker News habla de GPT4 simulando un servidor FTP en ftp.disney.com. Los usuarios debaten si esto se puede considerar o no "alucinante", a pesar del potencial de la IA para simular o "alucinar". La precisi\xf3n de las respuestas generadas por la IA y la percepci\xf3n de estos resultados como "alucinaciones" son tambi\xe9n puntos de discusi\xf3n. Otros temas tratados son: la posibilidad de que las pel\xedculas o programas de televisi\xf3n autogenerados carezcan de valor, el papel del espacio latente y el lenguaje en los LLM, el impacto de la tecnolog\xeda en la sociedad y las limitaciones de las capacidades actuales de la IA. Algunos usuarios advierten del peligro de sobreinterpretar las capacidades de la IA y se\xf1alan que a menudo se pasan por alto sus limitaciones.']}),"\n",(0,n.jsx)(a.h2,{id:"uso-de-mmap-para-que-llama-cargue-m\xe1s-r\xe1pido",children:"Uso de mmap para que LLaMA cargue m\xe1s r\xe1pido"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA utiliza mmap() para cargar los modelos 100 veces m\xe1s r\xe1pido, aumenta la estabilidad de la RAM y permite que m\xfaltiples procesos se ejecuten simult\xe1neamente. Los usuarios de Linux obtienen una mejora de 100x, mientras que Windows y MacOS obtienen 10x. El nuevo cargador mmap() ya est\xe1 disponible en GitHub bajo licencia MIT. El colaborador an\xf3nimo @Slaren a\xf1adi\xf3 soporte mmap() a LLaMA-7B, permitiendo tiempos de carga instant\xe1neos sin cambiar el formato del archivo. El nuevo formato de archivo alinea los tensores en un l\xedmite de 32 bytes. El post explora las posibles mejoras en la utilizaci\xf3n del disco y la alteraci\xf3n del rendimiento. Justine Tunney escribe sobre Twitter y Github en utilidades est\xe1ndar, dirigidas a expertos en la materia. Es clara y concisa, sin prejuicios ni declaraciones pol\xedticas o religiosas. Un usuario de Discussion Service comenta que el post de Tunney es un gran recurso para aprender."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nEl uso de mmap para hacer que LLaMA cargue m\xe1s r\xe1pido es el enfoque principal del art\xedculo, a pesar del drama en torno a la atribuci\xf3n y las cuestiones t\xe9cnicas en la secci\xf3n de comentarios. Se discuten los beneficios e inconvenientes de mmap, as\xed como los m\xe9ritos t\xe9cnicos de LLaMA.cpp de Facebook. Los usuarios discuten la utilidad de los cambios de LLaMA y los pros y los contras de varias caracter\xedsticas, proporcionando informaci\xf3n valiosa para los lectores expertos en tecnolog\xeda interesados en aprender m\xe1s sobre la IA y la implementaci\xf3n de modelos. El post destaca un enfoque de ingenier\xeda de sistemas a un problema y una tendencia que implica c\xf3digo propietario en bibliotecas, generando discusi\xf3n sobre el uso de Huge Pages y la dificultad de resolver cuellos de botella de IO. La revolucionaria mejora del rendimiento mediante mmap ha llamado la atenci\xf3n de los expertos en la materia."]})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(t,{...e})}):t(e)}}}]);